//! `--definition`: what this platform's service manager is told about the
//! node's Xmip Service, generated by `registration.rs` — the one place it is
//! written — for this executable, this configuration and the node it names.
//! `--install` registers the same definition (`install.rs`); this prints it
//! and registers nothing.

use std::path::{Path, PathBuf};
use std::process::ExitCode;

use xmip_audit::file_sink::DIRECTORY_VARIABLE;
use xmip_audit::program_audit::ProgramAudit;
use xmip_runtime::registration::{
    REFUSED, ServiceDefinition, ServiceManager, launchd_plist, systemd_unit,
    windows_service_arguments, windows_service_settings,
};

use crate::arguments::Arguments;
use crate::run;

/// The directory under the node's data directory its audit is written in,
/// which the service is told through `XMIP_AUDIT_DIRECTORY` (ADR-0062).
pub const AUDIT: &str = "audit";

/// Print the definition, or refuse in words.
pub fn print(audit: &ProgramAudit, arguments: &Arguments) -> ExitCode {
    match node_service(Path::new(&arguments.configuration))
        .and_then(|(_, service)| render(ServiceManager::for_target(), &service))
    {
        Ok(text) => {
            print!("{text}");
            ExitCode::SUCCESS
        }
        Err(problem) => {
            run::fail(audit, "definition", &format!("xmip-service: {problem}"));
            ExitCode::from(REFUSED)
        }
    }
}

/// The node configured at `configuration` and its Xmip Service, run by this
/// executable, its audit in the node's data directory.
///
/// # Errors
/// The configuration does not read, or a path cannot be said.
pub fn node_service(configuration: &Path) -> Result<(String, ServiceDefinition), String> {
    let shown = configuration.display().to_string();
    let (document, _, _) = xmip_runtime::start::read(&shown).map_err(|unread| unread.reason)?;
    let executable = std::env::current_exe()
        .map_err(|error| format!("cannot say where this executable is: {error}"))?;
    let configuration =
        std::path::absolute(configuration).map_err(|error| format!("{shown}: {error}"))?;
    let audit = audit_directory(&document.service.data_directory(&configuration))?;
    let node = document.service.node_name;
    let service = ServiceDefinition::for_node(
        &node,
        &text(&executable),
        &text(&configuration),
        &text(&installed_root(&executable)),
    )
    .with_variable(DIRECTORY_VARIABLE, &text(&audit));
    Ok((node, service))
}

/// The node's audit directory, under its data directory `data`.
///
/// # Errors
/// The path cannot be made absolute.
pub fn audit_directory(data: &Path) -> Result<PathBuf, String> {
    std::path::absolute(data.join(AUDIT)).map_err(|error| format!("{}: {error}", data.display()))
}

/// What `manager` is told, as text: for the Windows manager the `sc.exe
/// create` arguments one per line, then each setting that finishes the
/// registration after a blank line, its program first.
fn render(manager: ServiceManager, service: &ServiceDefinition) -> Result<String, String> {
    match manager {
        ServiceManager::Systemd => Ok(systemd_unit(service)),
        ServiceManager::Launchd => Ok(launchd_plist(service)),
        ServiceManager::WindowsScm => {
            let mut text: String = windows_service_arguments(service)
                .into_iter()
                .map(|argument| argument + "\n")
                .collect();
            for (program, arguments) in windows_service_settings(service) {
                text.push('\n');
                text.push_str(&program);
                text.push('\n');
                for argument in arguments {
                    text.push_str(&argument);
                    text.push('\n');
                }
            }
            Ok(text)
        }
        ServiceManager::None => Err("this platform has no service manager".to_string()),
    }
}

/// The installed layout's root, which the executable's `bin` sits in
/// (ADR-0015 clause 10); the executable's own directory where it sits in no
/// `bin`.
fn installed_root(executable: &Path) -> PathBuf {
    let directory = executable.parent().unwrap_or(executable);
    if directory.file_name().is_some_and(|name| name == "bin") {
        directory.parent().unwrap_or(directory).to_path_buf()
    } else {
        directory.to_path_buf()
    }
}

/// `path` as the text a service manager is told.
pub fn text(path: &Path) -> String {
    path.display().to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_root_is_the_layout_the_executable_is_installed_in() {
        let root = Path::new("/opt/xmip");
        assert_eq!(installed_root(&root.join("bin/xmip-service")), root);
        assert_eq!(
            installed_root(Path::new("/home/me/target/debug/xmip-service")),
            Path::new("/home/me/target/debug")
        );
    }

    #[test]
    fn each_manager_gets_its_own_form_of_the_one_definition() {
        let node = xmip_configure::fixture::test_cluster().node(0).name.clone();
        let service = ServiceDefinition::for_node(
            &node,
            "/opt/xmip/bin/xmip-service",
            "/opt/xmip/config/xmip-node.toml",
            "/opt/xmip",
        )
        .with_variable(DIRECTORY_VARIABLE, "/opt/xmip/data/audit");

        let unit = render(ServiceManager::Systemd, &service).expect("a unit");
        assert!(unit.contains("ExecStart=/opt/xmip/bin/xmip-service --configuration"));
        assert!(unit.contains("XMIP_AUDIT_DIRECTORY=/opt/xmip/data/audit"));
        let plist = render(ServiceManager::Launchd, &service).expect("a plist");
        assert!(plist.contains(&format!("<string>xmip-{node}</string>")));
        let scm = render(ServiceManager::WindowsScm, &service).expect("arguments");
        assert!(
            scm.starts_with(&format!("create\nxmip-{node}\nbinPath= ")),
            "{scm}"
        );
        assert!(scm.contains("\n\nsc.exe\ndescription\n"), "{scm}");
        assert!(scm.contains("\n\nreg.exe\nadd\n"), "{scm}");
        assert!(render(ServiceManager::None, &service).is_err());
    }
}
